    /// A backend that replays a pre-recorded script of [`ExecutionEvent`]s.
    struct FakeBackend {
        descriptor: BackendDescriptor,
        script: Vec<ExecutionEvent>,
        block_until_cancelled: bool,
    }

    impl FakeBackend {
        fn new(descriptor: BackendDescriptor, script: Vec<ExecutionEvent>) -> Self {
            Self {
                descriptor,
                script,
                block_until_cancelled: false,
            }
        }

        fn new_blocking(descriptor: BackendDescriptor) -> Self {
            Self {
                descriptor,
                script: Vec::new(),
                block_until_cancelled: true,
            }
        }
    }

    #[async_trait]
    impl ExecutionBackend for FakeBackend {
        fn descriptor(&self) -> BackendDescriptor {
            self.descriptor.clone()
        }

        fn capabilities(&self) -> BackendCapabilities {
            self.descriptor.capabilities.clone()
        }

        async fn execute(
            &self,
            request: ExecutionRequest,
            sink: broadcast::Sender<ExecutionEvent>,
            cancel: CancellationToken,
        ) -> Result<ExecutionResult, ExecutionError> {
            if self.block_until_cancelled {
                // Block until cancelled, then return Cancelled.
                cancel.cancelled().await;
                return Err(ExecutionError::Cancelled);
            }

            // Replay the script into the broadcast channel.
            for event in &self.script {
                if cancel.is_cancelled() {
                    return Err(ExecutionError::Cancelled);
                }
                let _ = sink.send(event.clone());
                // Yield briefly so the receiver can catch up.
                tokio::task::yield_now().await;
            }

            Ok(ExecutionResult {
                request_id: request.request_id,
                usage: ModelUsage::default(),
                cost: Cost::default(),
                finish_reason: "end_turn".into(),
            })
        }
    }

