    // -----------------------------------------------------------------------
    // Test 1: StartRun → Backend events → Completed
    // -----------------------------------------------------------------------

    /// Verifies that a StartRun command drives a FakeBackend that emits a
    /// TextDelta then completes, producing the expected ordered events.
    #[tokio::test]
    async fn normal_run_completes_with_expected_events() {
        // ── Setup ──────────────────────────────────────────────────────
        let agent_id = AgentId::new();
        let session_id = SessionId::new();
        let agent = test_agent(agent_id, session_id);

        let (task, _event_rx) = AgentTask::new(agent_id, 64, 64);

        let backend_descriptor = BackendDescriptor {
            id: BackendId::new(),
            name: "fake".into(),
            description: "Fake backend".into(),
            capabilities: BackendCapabilities {
                streaming: true,
                ..Default::default()
            },
        };

        let request_id = RequestId::new();

        let fake_backend = FakeBackend::new(
            backend_descriptor,
            vec![
                ExecutionEvent::TextDelta {
                    request_id,
                    delta: "Hello, world!".into(),
                },
                ExecutionEvent::Completed {
                    request_id,
                    result: ExecutionResult {
                        request_id,
                        usage: ModelUsage::default(),
                        cost: Cost::default(),
                        finish_reason: "end_turn".into(),
                    },
                },
            ],
        );

        let (event_sink, collected_events) = FakeEventSink::new();
        let cancel = CancellationToken::new();

        let mut runner = AgentRunner::new(
            agent,
            task,
            Arc::new(fake_backend),
            Arc::new(FakeToolRegistry),
            Arc::new(event_sink),
            cancel,
        );

        // ── Act ────────────────────────────────────────────────────────
        // Inject a StartRun command into the task's command channel.
        runner
            .task
            .commands_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "Hello".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Run the loop.
        runner.run().await;

        // ── Assert ─────────────────────────────────────────────────────
        let events = collected_events.lock().unwrap();
        let event_types: Vec<&str> = events
            .iter()
            .map(|e| match &e.event {
                AgentEvent::StateChanged { .. } => "StateChanged",
                AgentEvent::RunStarted { .. } => "RunStarted",
                AgentEvent::AssistantTextDelta { .. } => "AssistantTextDelta",
                AgentEvent::Completed { .. } => "Completed",
                _ => "Other",
            })
            .collect();

        // We expect at least: StateChanged(Idle→PreparingContext),
        // RunStarted, possibly StateChanged(PreparingContext→Streaming),
        // AssistantTextDelta, StateChanged(Streaming→Idle), Completed.
        assert!(
            event_types.contains(&"RunStarted"),
            "Expected RunStarted event, got {event_types:?}"
        );
        assert!(
            event_types.contains(&"AssistantTextDelta"),
            "Expected AssistantTextDelta event, got {event_types:?}"
        );
        assert!(
            event_types.contains(&"Completed"),
            "Expected Completed event, got {event_types:?}"
        );

        // Verify the Completed event contains Success.
        let completed = events
            .iter()
            .find(|e| matches!(e.event, AgentEvent::Completed { .. }))
            .expect("Completed event found");
        match &completed.event {
            AgentEvent::Completed { outcome } => {
                assert_eq!(*outcome, AgentOutcome::Success);
            }
            _ => panic!("Expected Completed event"),
        }

        // Verify ordering: RunStarted before Completed
        let run_started_idx = events
            .iter()
            .position(|e| matches!(e.event, AgentEvent::RunStarted { .. }))
            .expect("RunStarted");
        let completed_idx = events
            .iter()
            .position(|e| matches!(e.event, AgentEvent::Completed { .. }))
            .expect("Completed");
        assert!(
            run_started_idx < completed_idx,
            "RunStarted must appear before Completed"
        );

        // Verify agent_sequence is monotonic.
        let seqs: Vec<u64> = events.iter().map(|e| e.agent_sequence).collect();
        let sorted = {
            let mut s = seqs.clone();
            s.sort();
            s
        };
        assert_eq!(seqs, sorted, "agent_sequence must be monotonically increasing");
    }

    // -----------------------------------------------------------------------
    // Test 2: Cancellation mid-flight
    // -----------------------------------------------------------------------

    /// Verifies that a blocking FakeBackend cancelled mid-flight causes the
    /// runner to transition the agent to Cancelled and stops further backend
    /// events.
    #[tokio::test]
    async fn cancellation_mid_flight_transitions_to_cancelled() {
        // ── Setup ──────────────────────────────────────────────────────
        let agent_id = AgentId::new();
        let session_id = SessionId::new();
        let agent = test_agent(agent_id, session_id);

        let (task, _event_rx) = AgentTask::new(agent_id, 64, 64);

        let backend_descriptor = BackendDescriptor {
            id: BackendId::new(),
            name: "blocking-fake".into(),
            description: "Blocking fake backend".into(),
            capabilities: BackendCapabilities {
                streaming: true,
                ..Default::default()
            },
        };

        let fake_backend = FakeBackend::new_blocking(backend_descriptor);

        let (event_sink, collected_events) = FakeEventSink::new();

        // Create a cancellation root so we can trigger it from the test.
        let session_cancel = crate::cancellation::SessionCancellation::new();
        let runner_cancel = session_cancel.child_token();

        let mut runner = AgentRunner::new(
            agent,
            task,
            Arc::new(fake_backend),
            Arc::new(FakeToolRegistry),
            Arc::new(event_sink),
            runner_cancel,
        );

        // ── Act ────────────────────────────────────────────────────────
        // Inject StartRun, then cancel mid-flight.
        runner
            .task
            .commands_tx
            .send(AgentCommand::StartRun {
                input: UserInput {
                    text: "Hello".into(),
                    attachments: vec![],
                },
            })
            .await
            .expect("send StartRun");

        // Give the runner a moment to start processing.
        tokio::time::sleep(Duration::from_millis(50)).await;

        // Cancel the session.
        session_cancel.cancel();

        // Run the loop — it should detect cancellation, inject Cancel into
        // the agent, drain effects, and break.
        runner.run().await;

        // ── Assert ─────────────────────────────────────────────────────
        let events = collected_events.lock().unwrap();
        let event_types: Vec<&str> = events
            .iter()
            .map(|e| match &e.event {
                AgentEvent::StateChanged { .. } => "StateChanged",
                AgentEvent::RunStarted { .. } => "RunStarted",
                AgentEvent::Completed { .. } => "Completed",
                AgentEvent::Failed { .. } => "Failed",
                _ => "Other",
            })
            .collect();

        // We should have a Completed event with outcome Cancelled.
        let completed = events
            .iter()
            .find(|e| matches!(e.event, AgentEvent::Completed { .. }));
        assert!(
            completed.is_some(),
            "Expected a Completed event after cancellation, got {event_types:?}"
        );

        let completed = completed.unwrap();
        match &completed.event {
            AgentEvent::Completed { outcome } => {
                assert_eq!(
                    *outcome,
                    AgentOutcome::Cancelled,
                    "Expected Cancelled outcome after mid-flight cancellation"
                );
            }
            other => panic!("Expected Completed event, got {other:?}"),
        }

        // The agent should be in Cancelled state.
        assert_eq!(
            runner.agent.state.status,
            AgentStatus::Cancelled,
            "Agent status should be Cancelled after mid-flight cancellation"
        );

        // No Failed events should appear.
        let has_failed = events
            .iter()
            .any(|e| matches!(e.event, AgentEvent::Failed { .. }));
        assert!(!has_failed, "No Failed event expected after clean cancellation");

        // Verify agent_sequence is monotonic.
        let seqs: Vec<u64> = events.iter().map(|e| e.agent_sequence).collect();
        let sorted = {
            let mut s = seqs.clone();
            s.sort();
            s
        };
        assert_eq!(seqs, sorted, "agent_sequence must be monotonically increasing");
    }

    // -----------------------------------------------------------------------
    // Test 3: Stale backend events are discarded after run completion
    // -----------------------------------------------------------------------

    /// Verifies that backend events arriving after a run has completed are
    /// discarded (the agent's `backend_event` method filters by `active_run`).
    #[tokio::test]
    async fn stale_backend_events_are_discarded() {
        let agent_id = AgentId::new();
        let session_id = SessionId::new();
        let mut agent = test_agent(agent_id, session_id);

        // Set a non-matching active_run to simulate a completed run.
        let completed_run_id = RunId::new();
        let stale_run_id = RunId::new();
        agent.state.active_run = Some(completed_run_id);

        // Process a BackendEvent for a different run — should be discarded.
        let effects = agent.apply(AgentCommand::BackendEvent {
            run_id: stale_run_id,
            event: ExecutionEvent::TextDelta {
                request_id: RequestId::new(),
                delta: "stale".into(),
            },
        });

        // No effects should be produced.
        assert!(
            effects.is_empty(),
            "Stale backend event should produce no effects, got {effects:?}"
        );

        // Agent state should be unchanged.
        assert_eq!(
            agent.state.active_run,
            Some(completed_run_id),
            "active_run should remain unchanged"
        );
    }
}

