//! Session runtime — event bus, session state, and lifecycle.
//!
//! This module provides [`SessionEventBus`] — the per-session event aggregator
//! that merges event streams from all agent runners into a single ordered stream
//! for subscribers — and [`SessionRuntime`], the top-level orchestrator that
//! owns a session's root agent, cancellation scope, backend bindings, and
//! event bus.

use std::collections::HashMap;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};

use tokio::sync::{broadcast, mpsc};
use tokio_util::sync::CancellationToken;

use harness_core::agent::Agent;
use harness_core::capabilities::{AgentCapabilities, WorkspaceCapabilities};
use harness_protocol::backend::{
    BackendBinding, BackendCapabilities, BackendDescriptor, BackendReference,
};
use harness_protocol::commands::{AgentCommand, UserInput};
use harness_protocol::events::AgentEventEnvelope;
use harness_protocol::ids::{
    AgentId, BackendId, ConfigurationId, IntegrationId, SessionId,
};
use harness_protocol::tools::AgentToolset;
use harness_protocol::usage::AgentBudget;

use crate::agent_runner::{AgentRunner, AgentTask};
use crate::cancellation::SessionCancellation;
use crate::traits::{EventSink, ExecutionBackend, ToolRegistry};

// ---------------------------------------------------------------------------
// SessionStatus
// ---------------------------------------------------------------------------

/// The high-level status of a session.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SessionStatus {
    /// Session is ready to accept commands.
    Idle,
    /// A run is in progress on at least one agent.
    Running,
    /// All agent runs have completed successfully.
    Completed,
    /// The session was cancelled before all runs completed.
    Cancelled,
}

// ---------------------------------------------------------------------------
// SessionCommand
// ---------------------------------------------------------------------------

/// A command sent to a session to drive its execution.
///
/// These are the user-facing commands that the session translates into
/// [`AgentCommand`]s for the appropriate agent runner.
#[derive(Debug, Clone)]
pub enum SessionCommand {
    /// Start a new run with the given user input.
    Prompt(UserInput),
    /// Cancel the entire session.
    Cancel,
    /// Pause the session.
    Pause,
    /// Resume a paused session.
    Resume,
}

// ---------------------------------------------------------------------------
// SessionError
// ---------------------------------------------------------------------------

/// Errors that can occur during session operations.
#[derive(Debug, Clone)]
pub enum SessionError {
    /// The session was not found.
    SessionNotFound,
    /// The session is in an invalid state for the requested operation.
    InvalidState {
        /// The expected state.
        expected: String,
        /// The actual state.
        actual: String,
    },
    /// The operation was cancelled.
    Cancelled,
    /// A command channel was closed unexpectedly.
    ChannelClosed,
}

// ---------------------------------------------------------------------------
// SessionSnapshot
// ---------------------------------------------------------------------------

/// A lightweight read projection of the session's current state.
#[derive(Debug, Clone)]
pub struct SessionSnapshot {
    /// The session's unique identifier.
    pub session_id: SessionId,
    /// The session's current status.
    pub status: SessionStatus,
    /// The root agent's identifier.
    pub root_agent_id: AgentId,
    /// The number of agents in the session.
    pub agent_count: usize,
}

// ---------------------------------------------------------------------------
// SessionState
// ---------------------------------------------------------------------------

/// The durable state of a session.
#[derive(Debug, Clone)]
pub struct SessionState {
    /// All agents in this session, indexed by their [`AgentId`].
    pub agents: HashMap<AgentId, Agent>,
    /// The identifier of the root agent (created when the session starts).
    pub root_agent_id: AgentId,
    /// The session's current status.
    pub status: SessionStatus,
}

// ---------------------------------------------------------------------------
// BridgeEventSink — connects EventSink trait to broadcast channel
// ---------------------------------------------------------------------------

/// An [`EventSink`] implementation that forwards every event to a
/// [`broadcast::Sender`] so that the [`SessionEventBus`] can receive it.
///
/// Also forwards to an optional secondary [`EventSink`] (e.g. for persistence
/// or logging).
struct BridgeEventSink {
    /// The broadcast sender that the session bus subscribes to
    /// (i.e. `AgentTask.events`).
    bus_tx: broadcast::Sender<AgentEventEnvelope>,
    /// An optional external sink for persistence / logging.
    external_sink: Option<Arc<dyn EventSink>>,
}

impl EventSink for BridgeEventSink {
    fn send(&self, envelope: AgentEventEnvelope) {
        // Forward to the bus broadcast channel (for subscribers).
        let _ = self.bus_tx.send(envelope.clone());
        // Forward to the external sink if present.
        if let Some(ref sink) = self.external_sink {
            sink.send(envelope);
        }
    }
}

// ---------------------------------------------------------------------------
// SessionEventBus
// ---------------------------------------------------------------------------

/// Aggregates event broadcasts from all agent runners in a session and fans
/// them out to external subscribers as a single ordered stream.
///
/// # Ordering
///
/// Every event that flows through the bus receives a monotonically increasing
/// [`session_sequence`](AgentEventEnvelope::session_sequence) number.  This,
/// combined with the agent-local [`agent_sequence`](AgentEventEnvelope::agent_sequence),
/// allows consumers to reconstruct a total order across all agents in the
/// session.
///
/// # Lifecycle
///
/// 1. Create with [`SessionEventBus::new`].
/// 2. As each agent runner is spawned, call
///    [`register_agent`](SessionEventBus::register_agent) with the broadcast
///    sender from that runner's [`AgentTask`].
/// 3. Spawn the [`run`](SessionEventBus::run) loop as a background tokio task.
/// 4. External consumers obtain a receiver via
///    [`subscribe`](SessionEventBus::subscribe).
pub struct SessionEventBus {
    /// Broadcast receivers for each registered agent. Wrapped in a [`Mutex`]
    /// so that agents can be registered from any thread while the run loop
    /// polls them concurrently.
    receivers: Mutex<Vec<broadcast::Receiver<AgentEventEnvelope>>>,

    /// Shared sender for external subscribers carved from the broadcast
    /// channel created in [`new`](SessionEventBus::new).
    subscriber_sender: broadcast::Sender<AgentEventEnvelope>,

    /// Monotonically increasing session-level sequence counter. Every event
    /// that flows through the bus receives the next value before being fanned
    /// out.
    session_sequence: AtomicU64,
}

impl SessionEventBus {
    /// Create a new event bus with the given subscriber channel capacity.
    pub fn new(capacity: usize) -> Self {
        let (subscriber_sender, _) = broadcast::channel(capacity);
        Self {
            receivers: Mutex::new(Vec::new()),
            subscriber_sender,
            session_sequence: AtomicU64::new(0),
        }
    }

    /// Register a new agent's event source with the bus.
    ///
    /// The `sender` should be the [`broadcast::Sender`] from the agent's
    /// [`AgentTask::events`]. The bus creates a receiver and will poll it
    /// in the [`run`](SessionEventBus::run) loop.
    pub fn register_agent(
        &self,
        _agent_id: AgentId,
        sender: broadcast::Sender<AgentEventEnvelope>,
    ) {
        let rx = sender.subscribe();
        self.receivers
            .lock()
            .expect("receivers mutex poisoned")
            .push(rx);
    }

    /// Return a new subscriber receiver that will receive all session events.
    pub fn subscribe(&self) -> broadcast::Receiver<AgentEventEnvelope> {
        self.subscriber_sender.subscribe()
    }

    /// Run the event bus's forwarding loop.
    ///
    /// Polls every registered agent receiver via [`try_recv`],
    /// assigns a monotonically increasing `session_sequence` to each event,
    /// and forwards to all subscribers.  Exits when `bus_cancel` is
    /// triggered.
    pub async fn run(&self, bus_cancel: CancellationToken) {
        loop {
            if bus_cancel.is_cancelled() {
                break;
            }

            let mut had_data = false;

            let mut receivers = self
                .receivers
                .lock()
                .expect("receivers mutex poisoned");

            receivers.retain_mut(|rx| loop {
                match rx.try_recv() {
                    Ok(mut envelope) => {
                        let seq =
                            self.session_sequence.fetch_add(1, Ordering::Relaxed);
                        envelope.session_sequence = Some(seq);
                        let _ = self.subscriber_sender.send(envelope);
                        had_data = true;
                    }
                    Err(broadcast::error::TryRecvError::Empty) => break,
                    Err(broadcast::error::TryRecvError::Closed) => return false,
                    Err(broadcast::error::TryRecvError::Lagged(n)) => {
                        tracing::warn!("Session event bus lagged by {n} events");
                    }
                }
            });

            drop(receivers);

            if !had_data {
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
            } else {
                tokio::task::yield_now().await;
            }
        }
    }
}

// ---------------------------------------------------------------------------
// SessionRuntime
// ---------------------------------------------------------------------------

/// The top-level orchestrator for a single session.
///
/// Owns the session's identity, state, cancellation root, event bus, the
/// session's default execution backend, tool registry, and event sink.
pub struct SessionRuntime {
    /// The session's unique identifier.
    pub session_id: SessionId,
    /// The session's mutable state (agents, status, root agent id).
    pub state: SessionState,
    /// Hierarchical cancellation root for this session.
    pub cancellation: SessionCancellation,
    /// The event bus that aggregates agent event streams.
    ///
    /// Stored in [`Arc`] so a clone can be moved into the background
    /// forwarding task.
    pub event_bus: Arc<SessionEventBus>,
    /// The execution backend used for LLM requests.
    pub default_backend: Arc<dyn ExecutionBackend>,
    /// Registry of available tool executors.
    pub tool_registry: Arc<dyn ToolRegistry>,
    /// Sink for fully-enveloped agent events.
    pub event_sink: Arc<dyn EventSink>,
    /// Sender to the root agent's task command channel.
    root_agent_tx: mpsc::Sender<AgentCommand>,
}

impl SessionRuntime {
    /// Create a new session runtime.
    ///
    /// This constructor:
    ///
    /// 1. Creates a root [`Agent`] with empty capabilities.
    /// 2. Creates a [`SessionCancellation`] for hierarchical cancellation.
    /// 3. Creates a [`SessionEventBus`] and spawns its background forwarding
    ///    task.
    /// 4. Spawns the root agent's runner task.
    /// 5. Returns a fully initialised `SessionRuntime`.
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        session_id: SessionId,
        backend: Arc<dyn ExecutionBackend>,
        tool_registry: Arc<dyn ToolRegistry>,
        event_sink: Arc<dyn EventSink>,
    ) -> Self {
        // ── 1. Root agent ───────────────────────────────────────────
        let root_agent_id = AgentId::new();
        let root_agent = Agent::new(
            root_agent_id,
            session_id,
            None,
            String::new(),
            BackendBinding {
                reference: BackendReference {
                    integration: IntegrationId::new(),
                    configuration: ConfigurationId::new(),
                    model: None,
                },
                descriptor: BackendDescriptor {
                    id: BackendId::new(),
                    name: backend.descriptor().name,
                    description: backend.descriptor().description,
                    capabilities: backend.capabilities(),
                },
            },
            AgentCapabilities {
                tools: AgentToolset {
                    tools: HashMap::new(),
                },
                can_spawn_agents: false,
                max_child_depth: None,
                workspace: WorkspaceCapabilities {
                    can_read: false,
                    can_write: false,
                    can_search: false,
                },
                backend: BackendCapabilities::default(),
            },
            AgentBudget::default(),
        );

        // ── 2. Session state ─────────────────────────────────────────
        let mut agents = HashMap::new();
        agents.insert(root_agent_id, root_agent.clone());
        let state = SessionState {
            agents,
            root_agent_id,
            status: SessionStatus::Idle,
        };

        // ── 3. Cancellation ──────────────────────────────────────────
        let cancellation = SessionCancellation::new();

        // ── 4. Event bus ─────────────────────────────────────────────
        let event_bus = Arc::new(SessionEventBus::new(256));
        let bus_handle = Arc::clone(&event_bus);
        let bus_cancel = cancellation.child_token();
        tokio::spawn(async move {
            bus_handle.run(bus_cancel).await;
        });

        // ── 5. Agent task + runner ───────────────────────────────────
        let agent_cancel = cancellation.child_token();
        let (task, _event_rx) = AgentTask::new(root_agent_id, 64, 256);
        let root_agent_tx = task.commands_tx.clone();

        // Create a BridgeEventSink that forwards to both:
        //   a) the AgentTask.events broadcast (for SessionEventBus)
        //   b) the external event_sink (for persistence/logging)
        let bridge_sink = Arc::new(BridgeEventSink {
            bus_tx: task.events.clone(),
            external_sink: Some(event_sink.clone()),
        });

        let runner = AgentRunner::new(
            root_agent,
            task,
            backend.clone(),
            tool_registry.clone(),
            bridge_sink,
            agent_cancel,
        );

        // Register the agent's broadcast sender with the event bus
        // so the bus can read events forwarded by the BridgeEventSink.
        event_bus.register_agent(root_agent_id, runner.task.events.clone());

        // Spawn the runner task.
        tokio::spawn(async move {
            let mut runner = runner;
            runner.run().await;
        });

        // ── 6. Assemble ──────────────────────────────────────────────
        Self {
            session_id,
            state,
            cancellation,
            event_bus,
            default_backend: backend,
            tool_registry,
            event_sink,
            root_agent_tx,
        }
    }

    /// Send a command to the root agent's task channel.
    ///
    /// In this Phase 2 implementation, only the root agent is supported.
    pub async fn send_command(&self, command: SessionCommand) -> Result<(), SessionError> {
        let agent_command = match command {
            SessionCommand::Prompt(input) => AgentCommand::StartRun { input },
            SessionCommand::Cancel => AgentCommand::Cancel,
            SessionCommand::Pause => AgentCommand::Pause,
            SessionCommand::Resume => AgentCommand::Resume,
        };

        self.root_agent_tx
            .send(agent_command)
            .await
            .map_err(|_| SessionError::ChannelClosed)
    }

    /// Cancel the entire session.
    ///
    /// Triggers the hierarchical cancellation root and sends
    /// [`AgentCommand::Cancel`] to the root agent.
    pub async fn cancel(&self) {
        self.cancellation.cancel();
        let _ = self.root_agent_tx.send(AgentCommand::Cancel).await;
    }

    /// Returns a [`SessionSnapshot`] of the current session state.
    ///
    /// This is a pure read — no stored copy, just a point-in-time projection
    /// of live state.
    pub fn state_snapshot(&self) -> SessionSnapshot {
        SessionSnapshot {
            session_id: self.session_id,
            status: self.state.status,
            root_agent_id: self.state.root_agent_id,
            agent_count: self.state.agents.len(),
        }
    }
}

// ===========================================================================
// Tests
// ===========================================================================

#[cfg(test)]
mod tests {
    use std::collections::HashMap;
    use std::sync::Arc;
    use std::time::Duration;

    use tokio::sync::broadcast;
    use tokio_util::sync::CancellationToken;

    use harness_protocol::backend::{ExecutionEvent, ExecutionResult};
    use harness_protocol::commands::UserInput;
    use harness_protocol::events::{AgentEvent, AgentEventEnvelope, AgentOutcome};
    use harness_protocol::ids::{AgentId, RequestId, RunId, SessionId};
    use harness_protocol::usage::{Cost, ModelUsage};

    use crate::testing::{FakeBackend, FakeToolRegistry};
    use crate::traits::EventSink;

    use super::*;

    // -----------------------------------------------------------------------
    // Test: subscribing to the bus and sending SessionCommand::Prompt
    // produces a well-ordered stream and a Completed event
    // -----------------------------------------------------------------------

    /// Verifies that subscribing to the session event bus and sending
    /// `SessionCommand::Prompt` (translated to `AgentCommand::StartRun`)
    /// produces a well-ordered stream including `RunStarted`, wrapped
    /// `AgentEvent`s, and `Completed`.
    #[tokio::test]
    async fn session_prompt_produces_ordered_event_stream() {
        // ── Setup ──────────────────────────────────────────────────────
        let session_id = SessionId::new();
        let request_id = RequestId::new();

        let backend = Arc::new(
            FakeBackend::new()
                .with_events(vec![
                    ExecutionEvent::TextDelta {
                        request_id,
                        delta: "Hello, world!".into(),
                    },
                    ExecutionEvent::Completed {
                        request_id,
                        result: ExecutionResult {
                            request_id,
                            usage: ModelUsage::default(),
                            cost: Cost::default(),
                            finish_reason: "end_turn".into(),
                        },
                    },
                ])
                .with_result(ExecutionResult {
                    request_id,
                    usage: ModelUsage::default(),
                    cost: Cost::default(),
                    finish_reason: "end_turn".into(),
                }),
        );

        let tool_registry = Arc::new(FakeToolRegistry::new(HashMap::new(), Vec::new()));

        // Use a no-op event sink for the external persistence/logging path.
        struct NoopSink;
        impl EventSink for NoopSink {
            fn send(&self, _envelope: AgentEventEnvelope) {}
        }

        let runtime = SessionRuntime::new(
            session_id,
            backend,
            tool_registry,
            Arc::new(NoopSink),
        );

        // Subscribe to the event bus before sending any command.
        let mut subscriber = runtime.event_bus.subscribe();

        // ── Act ────────────────────────────────────────────────────────
        runtime
            .send_command(SessionCommand::Prompt(UserInput {
                text: "Hello".into(),
                attachments: vec![],
            }))
            .await
            .expect("send_command should succeed");

        // ── Collect events from the bus subscriber ─────────────────────
        let mut collected: Vec<AgentEventEnvelope> = Vec::new();
        let deadline = tokio::time::Instant::now() + Duration::from_secs(3);

        while tokio::time::Instant::now() < deadline {
            match tokio::time::timeout(Duration::from_millis(200), subscriber.recv()).await {
                Ok(Ok(envelope)) => {
                    collected.push(envelope);
                }
                Ok(Err(broadcast::error::RecvError::Closed)) => break,
                Ok(Err(broadcast::error::RecvError::Lagged(n))) => {
                    tracing::warn!("Subscriber lagged by {n} events");
                }
                Err(_) => {
                    // Timeout — no more events available.
                    if !collected.is_empty() {
                        break;
                    }
                }
            }

            // Stop once we've seen a Completed event.
            if collected
                .iter()
                .any(|e| matches!(e.event, AgentEvent::Completed { .. }))
            {
                break;
            }
        }

        // ── Assert event types and ordering ────────────────────────────
        assert!(
            !collected.is_empty(),
            "Expected at least one event from subscriber, got none"
        );

        let event_types: Vec<&str> = collected
            .iter()
            .map(|e| match &e.event {
                AgentEvent::StateChanged { .. } => "StateChanged",
                AgentEvent::RunStarted { .. } => "RunStarted",
                AgentEvent::AssistantTextDelta { .. } => "AssistantTextDelta",
                AgentEvent::Completed { .. } => "Completed",
                _ => "Other",
            })
            .collect();

        assert!(
            event_types.contains(&"RunStarted"),
            "Expected RunStarted, got {event_types:?}"
        );
        assert!(
            event_types.contains(&"AssistantTextDelta"),
            "Expected AssistantTextDelta, got {event_types:?}"
        );
        assert!(
            event_types.contains(&"Completed"),
            "Expected Completed, got {event_types:?}"
        );

        // Completed → Success
        let completed = collected
            .iter()
            .find(|e| matches!(e.event, AgentEvent::Completed { .. }))
            .expect("Completed event");
        match &completed.event {
            AgentEvent::Completed { outcome } => assert_eq!(*outcome, AgentOutcome::Success),
            _ => panic!("Expected Completed with Success"),
        }

        // Ordering: RunStarted before Completed
        let rs_idx = collected
            .iter()
            .position(|e| matches!(e.event, AgentEvent::RunStarted { .. }))
            .expect("RunStarted");
        let co_idx = collected
            .iter()
            .position(|e| matches!(e.event, AgentEvent::Completed { .. }))
            .expect("Completed");
        assert!(rs_idx < co_idx, "RunStarted must appear before Completed");

        // ── Assert session_sequence assignment ─────────────────────────
        for e in &collected {
            assert!(
                e.session_sequence.is_some(),
                "Missing session_sequence on event {e:?}"
            );
        }

        let seqs: Vec<u64> = collected.iter().filter_map(|e| e.session_sequence).collect();
        let mut sorted = seqs.clone();
        sorted.sort();
        assert_eq!(seqs, sorted, "session_sequence must be monotonically increasing");

        let mut deduped = seqs.clone();
        deduped.sort();
        deduped.dedup();
        assert_eq!(seqs.len(), deduped.len(), "session_sequence values not unique");

        // All events carry the correct session_id.
        for e in &collected {
            assert_eq!(e.session_id, session_id, "Wrong session_id");
        }

        // ── Status snapshot ────────────────────────────────────────────
        let snapshot = runtime.state_snapshot();
        assert_eq!(snapshot.status, SessionStatus::Idle);
        assert_eq!(snapshot.session_id, session_id);
        assert_eq!(snapshot.root_agent_id, runtime.state.root_agent_id);
    }

    // -----------------------------------------------------------------------
    // Test: bus assigns monotonic session_sequence
    // -----------------------------------------------------------------------

    /// Verifies that events forwarded through the bus receive monotonically
    /// increasing `session_sequence` values.
    #[tokio::test]
    async fn bus_assigns_monotonic_session_sequence() {
        let bus = Arc::new(SessionEventBus::new(64));
        let (agent_tx, _) = broadcast::channel(64);
        let push_tx = agent_tx.clone();

        let agent_id = AgentId::new();
        bus.register_agent(agent_id, agent_tx);

        let mut subscriber = bus.subscribe();

        let bus_clone = Arc::clone(&bus);
        let bus_cancel = CancellationToken::new();
        tokio::spawn(async move {
            bus_clone.run(bus_cancel).await;
        });

        let session_id = SessionId::new();
        let make_event = |seq: u64| AgentEventEnvelope {
            event_id: harness_protocol::ids::EventId::new(),
            session_id,
            agent_id,
            parent_agent_id: None,
            run_id: Some(RunId::new()),
            agent_sequence: seq,
            session_sequence: None,
            timestamp: harness_protocol::ids::Timestamp::now(),
            visibility: harness_protocol::events::EventVisibility::User,
            event: AgentEvent::RunStarted {
                run_id: RunId::new(),
            },
        };

        push_tx.send(make_event(1)).unwrap();
        push_tx.send(make_event(2)).unwrap();
        push_tx.send(make_event(3)).unwrap();

        tokio::time::sleep(Duration::from_millis(100)).await;

        let mut collected: Vec<AgentEventEnvelope> = Vec::new();
        loop {
            match subscriber.try_recv() {
                Ok(e) => collected.push(e),
                Err(broadcast::error::TryRecvError::Empty) => break,
                Err(_) => break,
            }
        }

        assert_eq!(collected.len(), 3, "Expected 3 events, got {}", collected.len());
        for (i, e) in collected.iter().enumerate() {
            assert_eq!(
                e.session_sequence,
                Some(i as u64),
                "session_sequence should be {i}, got {:?}",
                e.session_sequence
            );
        }
    }
}

//! Session client — external API for interacting with a session.
//!
//! This module provides the frontend-facing `SessionClient` handle for a
single session. It wraps the session runtime and translates user‑facing
`SessionCommand`s into agent‑level commands, while offering lightweight
read projections (snapshots) and an ordered event subscription view.

use std::sync::Arc;

use tokio::sync::broadcast;

use harness_protocol::commands::{AgentCommand, UserInput};
use harness_protocol::events::AgentEventEnvelope;
use harness_protocol::ids::{AgentId, SessionId, Timestamp};
use harness_protocol::usage::{AgentUsageSnapshot, SessionUsageSnapshot};

use crate::session_runtime::{SessionCommand, SessionError, SessionRuntime, SessionStatus, SessionSnapshot as RuntimeSessionSnapshot};

/// A lightweight read projection of the session's current state.
///
/// This is a pure function of live state — no stored copy — giving callers
the current snapshot of the session status, root agent status, and usage.
#[derive(Debug, Clone)]
pub struct SessionSnapshot {
    /// The session's unique identifier.
    pub session_id: SessionId,
    /// High‑level session status.
    pub status: SessionStatus,
    /// The root agent’s identifier (convenience field).
    pub root_agent_id: AgentId,
    /// The root agent’s detailed status.
    ///
    /// Contains information about the root agent’s current run,
    /// its operation, backend, and usage tracking.
    pub root_agent_status: AgentUsageSnapshot,
    /// Aggregated usage information across the session.
    pub usage: SessionUsageSnapshot,
    /// When this snapshot was taken.
    pub timestamp: Timestamp,
}

impl From<RuntimeSessionSnapshot> for SessionSnapshot {
    fn from(runtime_snapshot: RuntimeSessionSnapshot) -> Self {
        // For Phase 2 we create a minimal root agent status snapshot.
        // In a full implementation this would be derived from the live runtime
        // (e.g. reading the root agent's AgentState from crate::agent_state).
        let root_agent_id = runtime_snapshot.root_agent_id;
        let root_agent_status = AgentUsageSnapshot {
            id: root_agent_id,
            parent_id: None,
            // Default placeholder status – Phase 2 uses a trivial no‑op fake.
            status: harness_protocol::events::AgentStatus::Idle,
            current_operation: None,
            backend: harness_protocol::backend::BackendDescriptor {
                id: harness_protocol::ids::BackendId::new(),
                name: "<phase2-fake>".to_string(),
                description: "Fake backend for Phase 2".to_string(),
                capabilities: harness_protocol::backend::BackendCapabilities::default(),
            },
            usage: harness_protocol::usage::AgentUsageSnapshot::default(),
        };

        Self {
            session_id: runtime_snapshot.session_id,
            status: runtime_snapshot.status,
            root_agent_id,
            root_agent_status,
            usage: SessionUsageSnapshot::default(),
            timestamp: harness_protocol::ids::Timestamp::now(),
        }
    }
}

/// The frontend‑facing handle for a live session.
///
/// Owns an `Arc<SessionRuntime>` and provides translations between user‑facing
/// `SessionCommand`s and the runtime’s internal commands. Also offers a stable
/// ordered stream of events via `subscribe()`.
pub struct SessionClient {
    /// The runtime that owns the session’s agents and event bus.
    runtime: Arc<SessionRuntime>,
    /// An additional broadcast receiver over the session’s event bus.
    ///
    /// The client creates a new receiver for each subscriber, mirroring the
    /// `SessionEventBus::subscribe` API but returning a fresh handle for the
    /// caller (so that multiple callers can each observe the entire event
    /// stream).
    event_receiver: broadcast::Receiver<AgentEventEnvelope>,
}

impl SessionClient {
    /// Create a new session client for the given runtime.
    ///
    /// The client subscribes to the runtime’s event bus and will receive
    /// all events published to that bus (including agent events, bus
    /// sequencing wraps, etc.).
    pub fn new(runtime: Arc<SessionRuntime>) -> Self {
        let event_receiver = runtime.event_bus.subscribe();
        Self {
            runtime,
            event_receiver,
        }
    }

    /// Send a user‑facing command to the session.
    ///
    /// Commands are translated into the corresponding [`AgentCommand`]s and
    /// routed through the [`SessionRuntime`]’s `send_command` method. The
    /// supported commands are:
    ///
    /// * `SessionCommand::Prompt(UserInput)` → [`AgentCommand::StartRun`]
    /// * `SessionCommand::Cancel` → [`AgentCommand::Cancel`]
    /// * `SessionCommand::Pause` → [`AgentCommand::Pause`]
    /// * `SessionCommand::Resume` → [`AgentCommand::Resume`]
    pub async fn send(&self, command: SessionCommand) -> Result<(), SessionError> {
        self.runtime.send_command(command).await
    }

    /// Take a lightweight snapshot of the session’s current live state.
    ///
    /// The snapshot is a pure read‑only projection of the runtime’s current
    /// state: no stored copy is kept, the data is taken directly from the
    /// runtime’s internal structures.
    pub fn snapshot(&self) -> SessionSnapshot {
        let runtime_snapshot = self.runtime.state_snapshot();
        runtime_snapshot.into()
    }

    /// Return a new subscriber receiver that will observe all session events.
    ///
    /// Each call returns a fresh receiver channel, so independent callers can
    /// each watch the same ordered stream of events (e.g. for UI updates or
    /// logging).
    pub fn subscribe(&mut self) -> broadcast::Receiver<AgentEventEnvelope> {
        self.runtime.event_bus.subscribe()
    }

    /// Consume this client and return its underlying [`SessionRuntime`].
    ///
    /// Useful for advanced integrations that need direct access to the runtime
    /// (e.g. cancellation hooks, diagnostics).
    pub fn into_runtime(self) -> Arc<SessionRuntime> {
        self.runtime
    }
}

