//! Integration test: full e2e session with scripted [`FakeBackend`] verifying the exact
//! ordered [`AgentEvent`] sequence emitted for a prompt that streams assistant text.
//!
//! This is the Phase 2 goal acceptance test (spec §71 Phase 2 goal verbatim):
//!
//! > `session.send(prompt)` / `session.subscribe()` works end-to-end against a
//! > fake backend, producing the canonical event sequence:
//! > `RunStarted → AssistantMessageStarted → AssistantTextDelta(x2) →
//! >  AssistantMessageCompleted → UsageUpdated → Completed`

use std::sync::Arc;

use harness_core::agent::Agent;
use harness_core::capabilities::{AgentCapabilities, WorkspaceCapabilities};
use harness_engine::{Harness, HarnessError};
use harness_protocol::backend::{
    BackendCapabilities, BackendDescriptor, ExecutionContext, ExecutionError, ExecutionEvent,
    ExecutionRequest, ExecutionResult,
};
use harness_protocol::commands::AgentCommand;
use harness_protocol::events::{AgentEvent, AgentEventEnvelope, EventVisibility};
use harness_protocol::ids::{
    AgentId, BackendId, EventId, RequestId, RunId, SessionId, Timestamp,
};
use harness_protocol::tools::AgentToolset;
use harness_protocol::usage::{AgentBudget, ModelUsage, Cost};
use harness_runtime::testing::fake_backend::FakeBackend;
use harness_runtime::traits::ToolRegistry;
use tokio::sync::broadcast;
use harness_core::agent_state::AgentState;

/// A deterministic [`ExecutionBackend`] that replays a fixed script of
/// [`ExecutionEvent`]s and returns a pre-set [`ExecutionResult`].
///
/// Used to drive predictable event sequences through the agent state machine
/// and session runtime without requiring a live model API.
struct ScriptedBackend {
    descriptor: BackendDescriptor,
    script: Vec<ExecutionEvent>,
    finish: ExecutionResult,
}

impl ScriptedBackend {
    fn new(script: Vec<ExecutionEvent>, finish: ExecutionResult) -> Self {
        Self {
            descriptor: BackendDescriptor {
                id: BackendId::new(),
                name: "scripted".into(),
                description: "Scripted test backend".into(),
                capabilities: BackendCapabilities {
                    streaming: true,
                    ..Default::default()
                },
            },
            script,
            finish,
        }
    }
}

#[async_trait::async_trait]
impl harness_runtime::traits::ExecutionBackend for ScriptedBackend {
    fn descriptor(&self) -> BackendDescriptor {
        self.descriptor.clone()
    }

    fn capabilities(&self) -> BackendCapabilities {
        self.descriptor.capabilities
    }

    async fn execute(
        &self,
        _request: ExecutionRequest,
        _context: ExecutionContext,
        events: tokio::sync::mpsc::UnboundedSender<ExecutionEvent>,
        _cancel: tokio_util::sync::CancellationToken,
    ) -> Result<ExecutionResult, ExecutionError> {
        for event in &self.script {
            let _ = events.send(event.clone());
        }
        Ok(self.finish.clone())
    }
}

