// ---------------------------------------------------------------------------
// Helper: subscribe to a broadcast, drain events, return them in order
// ---------------------------------------------------------------------------

/// Collects all [`AgentEvent`]s currently buffered in the receiver without
/// blocking – useful for assertions after the event loop has drained.
fn drain_events(rx: &mut broadcast::Receiver<AgentEventEnvelope>) -> Vec<AgentEvent> {
    let mut events = Vec::new();
    while let Ok(envelope) = rx.try_recv() {
        events.push(envelope.event);
    }
    events
}

// ---------------------------------------------------------------------------
// session_send_subscribe_e2e
// ---------------------------------------------------------------------------

/// Phase 2 acceptance test: script a backend to emit two `TextDelta` events
/// followed by `Completed`, start a session, send a prompt, subscribe, and
/// verify the exact ordered `AgentEvent` sequence.
#[tokio::test]
async fn session_send_subscribe_e2e() {
    // ── Arrange: scripted backend ─────────────────────────────────────────
    //
    // The backend will stream:
    //   TextDelta("Hello ") → TextDelta("world!") → Completed
    //
    // The agent state machine should translate these into:
    //   StateChanged(Idle → PreparingContext)
    //   RunStarted
    //   AssistantMessageStarted
    //   AssistantTextDelta("Hello ")
    //   AssistantTextDelta("world!")
    //   AssistantMessageCompleted
    //   UsageUpdated
    //   StateChanged(Streaming → Idle)
    //   Completed { outcome: Success }

    let request_id = RequestId::new();
    let run_id = RunId::new();

    let script = vec![
        ExecutionEvent::TextDelta {
            request_id,
            delta: "Hello ".into(),
        },
        ExecutionEvent::TextDelta {
            request_id,
            delta: "world!".into(),
        },
        ExecutionEvent::Completed {
            request_id,
            result: ExecutionResult {
                request_id,
                usage: ModelUsage::default(),
                cost: Cost::default(),
                finish_reason: "end_turn".into(),
            },
        },
    ];

    let finish = ExecutionResult {
        request_id,
        usage: ModelUsage::default(),
        cost: Cost::default(),
        finish_reason: "end_turn".into(),
    };

    let backend = Arc::new(ScriptedBackend::new(script, finish));

    // Empty tool registry – no tools needed for this test.
    let tool_registry = Arc::new(ToolRegistry::new());

    // ── Act: builder chain ────────────────────────────────────────────────
    //
    //   harness.session().backend(fake_backend).tools(fake_toolset).start().await?
    //
    // followed by handle.send(prompt) and handle.subscribe().

    let mut handle = Harness::new()
        .session()
        .backend(backend)
        .tools(tool_registry)
        .start()
        .await
        .expect("SessionBuilder::start() should succeed");

    // Subscribe before sending the prompt so we don't miss events.
    let mut rx = handle.subscribe();

    // Send a prompt – this kicks off StartRun → backend execution.
    handle
        .send("hello from test")
        .await
        .expect("SessionHandle::send() should succeed");

    // ── Collect events ────────────────────────────────────────────────────
    //
    // The session runs asynchronously.  We poll the broadcast receiver
    // with a short sleep-spin to let the event loop drain its effects.
    // (In a real app you'd await each event; here we batch-collect for
    // assertion simplicity.)

    let mut all_events: Vec<AgentEvent> = Vec::new();

    // Spin a few times to let the async runtime process commands and
    // emit events into the broadcast channel.
    for _ in 0..50 {
        let batch = drain_events(&mut rx);
        if !batch.is_empty() {
            all_events.extend(batch);
            // Once we see a Completed event, we're done.
            if all_events.iter().any(|e| matches!(e, AgentEvent::Completed { .. })) {
                break;
            }
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }

    // ── Assert the exact ordered event sequence ───────────────────────────
    //
    // Expected sequence (spec §71 Phase 2 goal):
    //   0. StateChanged(Idle → PreparingContext)
    //   1. RunStarted
    //   2. AssistantMessageStarted
    //   3. AssistantTextDelta("Hello ")
    //   4. AssistantTextDelta("world!")
    //   5. AssistantMessageCompleted
    //   6. UsageUpdated
    //   7. Completed { outcome: Success }

    // Filter out StateChanged events and verify the core sequence.
    let core_events: Vec<&AgentEvent> = all_events
        .iter()
        .filter(|e| !matches!(e, AgentEvent::StateChanged { .. }))
        .collect();

    assert!(
        core_events.len() >= 6,
        "expected at least 6 non-StateChanged events (RunStarted, AssistantMessageStarted, \
         2x AssistantTextDelta, AssistantMessageCompleted, UsageUpdated, Completed); got {}: {:?}",
        core_events.len(),
        core_events
    );

    // 0. RunStarted
    assert!(
        matches!(core_events[0], AgentEvent::RunStarted { .. }),
        "event[0] should be RunStarted, got {:?}",
        core_events[0]
    );

    // 1. AssistantMessageStarted
    assert!(
        matches!(core_events[1], AgentEvent::AssistantMessageStarted { .. }),
        "event[1] should be AssistantMessageStarted, got {:?}",
        core_events[1]
    );

    // 2. AssistantTextDelta("Hello ")
    assert!(
        matches!(&core_events[2], AgentEvent::AssistantTextDelta { delta, .. } if delta == "Hello "),
        "event[2] should be AssistantTextDelta(\"Hello \"), got {:?}",
        core_events[2]
    );

    // 3. AssistantTextDelta("world!")
    assert!(
        matches!(&core_events[3], AgentEvent::AssistantTextDelta { delta, .. } if delta == "world!"),
        "event[3] should be AssistantTextDelta(\"world!\"), got {:?}",
        core_events[3]
    );

    // 4. AssistantMessageCompleted
    assert!(
        matches!(core_events[4], AgentEvent::AssistantMessageCompleted { .. }),
        "event[4] should be AssistantMessageCompleted, got {:?}",
        core_events[4]
    );

    // 5. UsageUpdated
    assert!(
        matches!(core_events[5], AgentEvent::UsageUpdated { .. }),
        "event[5] should be UsageUpdated, got {:?}",
        core_events[5]
    );

    // 6. Completed
    assert!(
        matches!(core_events[6], AgentEvent::Completed { outcome } if *outcome == harness_protocol::events::AgentOutcome::Success),
        "event[6] should be Completed(Success), got {:?}",
        core_events[6]
    );

    // Verify ordering: RunStarted index < AssistantMessageStarted index < delta1 index <
    // delta2 index < AssistantMessageCompleted index < UsageUpdated index < Completed index.
    let run_started_idx = all_events.iter().position(|e| matches!(e, AgentEvent::RunStarted { .. }));
    let msg_started_idx = all_events.iter().position(|e| matches!(e, AgentEvent::AssistantMessageStarted { .. }));
    let delta1_idx = all_events.iter().position(|e| matches!(e, AgentEvent::AssistantTextDelta { delta, .. } if delta == "Hello "));
    let delta2_idx = all_events.iter().position(|e| matches!(e, AgentEvent::AssistantTextDelta { delta, .. } if delta == "world!"));
    let msg_completed_idx = all_events.iter().position(|e| matches!(e, AgentEvent::AssistantMessageCompleted { .. }));
    let usage_idx = all_events.iter().position(|e| matches!(e, AgentEvent::UsageUpdated { .. }));
    let completed_idx = all_events.iter().position(|e| matches!(e, AgentEvent::Completed { .. }));

    assert!(run_started_idx < msg_started_idx, "RunStarted should precede AssistantMessageStarted");
    assert!(msg_started_idx < delta1_idx, "AssistantMessageStarted should precede first AssistantTextDelta");
    assert!(delta1_idx < delta2_idx, "first AssistantTextDelta should precede second");
    assert!(delta2_idx < msg_completed_idx, "second AssistantTextDelta should precede AssistantMessageCompleted");
    assert!(msg_completed_idx < usage_idx, "AssistantMessageCompleted should precede UsageUpdated");
    assert!(usage_idx < completed_idx, "UsageUpdated should precede Completed");
}

