```rust
//! Session client — external API for interacting with a session.
//!
//! This module provides the frontend-facing `SessionClient` handle for a
//! single session. It wraps the session runtime and translates user‑facing
//! `SessionCommand`s into agent‑level commands, while offering lightweight
//! read projections (snapshots) and an ordered event subscription view.

use std::sync::Arc;

use tokio::sync::broadcast;

use harness_protocol::commands::{AgentCommand, UserInput};
use harness_protocol::events::AgentEventEnvelope;
use harness_protocol::ids::{AgentId, SessionId, Timestamp};
use harness_protocol::usage::{AgentUsageSnapshot, SessionUsageSnapshot};

/// A lightweight read projection of the session's current state.
///
/// This is a pure function of live state — no stored copy — giving callers
/// the current snapshot of the session status, root agent status, and usage.
#[derive(Debug, Clone)]
pub struct SessionSnapshot {
    /// The session's unique identifier.
    pub session_id: SessionId,
    /// High‑level session status.
    pub status: SessionStatus,
    /// The root agent’s detailed status.
    pub root_agent_status: AgentUsageSnapshot,
    /// Aggregated usage information across the session.
    pub usage: SessionUsageSnapshot,
    /// When this snapshot was taken.
    pub timestamp: Timestamp,
}

/// The frontend‑facing handle for a live session.
///
/// Owns an `Arc<SessionRuntime>` and provides translations between user‑facing
/// `SessionCommand`s and the runtime’s internal commands. Also offers a stable
/// ordered stream of events via `subscribe()`.
pub struct SessionClient {
    /// The runtime that owns the session’s agents and event bus.
    runtime: Arc<SessionRuntime>,
    /// An additional broadcast receiver over the session’s event bus.
    ///
    /// The client creates a new receiver for each subscriber, mirroring the
    /// `SessionEventBus::subscribe` API but returning a fresh handle for the
    /// caller (so that multiple callers can each observe the entire event
    /// stream).
    event_receiver: broadcast::Receiver<AgentEventEnvelope>,
}

impl SessionClient {
    /// Create a new session client for the given runtime.
    ///
    /// The client subscribes to the runtime’s event bus and will receive
    /// all events published to that bus (including agent events, bus
    /// sequencing wraps, etc.).
    pub fn new(runtime: Arc<SessionRuntime>) -> Self {
        let event_receiver = runtime.event_bus.subscribe();
        Self {
            runtime,
            event_receiver,
        }
    }

    /// Send a user‑facing command to the session.
    ///
    /// Commands are translated into the corresponding [`AgentCommand`]s and
    /// routed through the [`SessionRuntime`]’s `send_command` method. The
    /// supported commands are:
    ///
    /// * `SessionCommand::Prompt(UserInput)` → [`AgentCommand::StartRun`]
    /// * `SessionCommand::Cancel` → [`AgentCommand::Cancel`]
    /// * `SessionCommand::Pause` → [`AgentCommand::Pause`]
    /// * `SessionCommand::Resume` → [`AgentCommand::Resume`]
    pub async fn send(&self, command: SessionCommand) -> Result<(), SessionError> {
        self.runtime.send_command(command).await
    }

    /// Take a lightweight snapshot of the session’s current live state.
    ///
    /// The snapshot is a pure read‑only projection of the runtime’s current
    /// state: no stored copy is kept, the data is taken directly from the
    /// runtime’s internal structures.
    pub fn snapshot(&self) -> SessionSnapshot {
        // Get basic runtime snapshot
        let runtime_snapshot = self.runtime.state_snapshot();

        // For Phase 2, we create a minimal root agent status.
        // This would be properly implemented using runtime's agent state.
        let root_agent_id = runtime_snapshot.root_agent_id;
        let root_agent_status = AgentUsageSnapshot {
            id: root_agent_id,
            parent_id: None,
            // Use the same status as the session for now
            status: match runtime_snapshot.status {
                SessionStatus::Idle => SessionStatus::Idle,
                SessionStatus::Running => SessionStatus::Running,
                SessionStatus::Completed => SessionStatus::Completed,
                SessionStatus::Cancelled => SessionStatus::Cancelled,
            },
            current_operation: None,
            backend: crate::runtime::backend::BackendDescriptor::default(),
            usage: AgentUsageSnapshot::default(),
        };

        SessionSnapshot {
            session_id: runtime_snapshot.session_id,
            status: runtime_snapshot.status,
            root_agent_status,
            usage: SessionUsageSnapshot::default(),
            timestamp: Timestamp::now(),
        }
    }

    /// Return a new subscriber receiver that will observe all session events.
    ///
    /// Each call returns a fresh receiver channel, so independent callers can
    /// each watch the same ordered stream of events (e.g. for UI updates or
    /// logging).
    pub fn subscribe(&mut self) -> broadcast::Receiver<AgentEventEnvelope> {
        self.runtime.event_bus.subscribe()
    }
}

/// Commands that users can send to control a session.
///
/// These high‑level commands are translated into lower‑level agent commands
/// by the `SessionClient` when sending them to the runtime.
#[derive(Debug, Clone)]
pub enum SessionCommand {
    /// Start a new run with the given user input.
    Prompt(UserInput),
    /// Cancel the entire session.
    Cancel,
    /// Pause the session.
    Pause,
    /// Resume a paused session.
    Resume,
}

/// Errors that can occur during session operations.
#[derive(Debug, Clone)]
pub enum SessionError {
    /// The session was not found.
    SessionNotFound,
    /// The session is in an invalid state for the requested operation.
    InvalidState {
        /// The expected state.
        expected: String,
        /// The actual state.
        actual: String,
    },
    /// The operation was cancelled.
